package numbers

func AddFloat32(a float32, b float32) float32 {
	return a + b
}

func SubFloat32(a float32, b float32) float32 {
	return a - b
}

func MulFloat32(a float32, b float32) float32 {
	return a * b
}

func DivFloat32(a float32, b float32) float32 {
	return a / b
}

func NegFloat32(a float32) float32 {
	return -a
}

func AddFloat64(a float64, b float64) float64 {
	return a + b
}

func SubFloat64(a float64, b float64) float64 {
	return a - b
}

func MulFloat64(a float64, b float64) float64 {
	return a * b
}

func DivFloat64(a float64, b float64) float64 {
	return a / b
}

func NegFloat64(a float64) float64 {
	return -a
}
